contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint x) public payable {
        // fund the contract so it has enough balance to withdraw
        require(address(this).balance >= x, "not enough balance");
        (bool sent, ) = address(c).call{value: x}("");
        require(sent, "funding failed");

        uint beforeBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        try c.withdraw(x) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(this).balance == beforeThisBalance + x);
            assert(address(c).balance == beforeBalance - x);
        } else {
            assert(address(this).balance == beforeThisBalance);
            assert(address(c).balance == beforeBalance);
        }
    }

    receive() external payable {}
}

