contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint dummy) public {
        // The test contract is the owner because it deployed c.
        // To test the onlyOwner modifier, we must simulate a call from a non-owner.
        // We cannot change msg.sender for external calls from this contract.
        // Therefore, a direct call from this contract will always be from the owner.
        // We need a different approach: the contract cannot impersonate another sender.
        // The only way to test non-owner behavior is if the owner is not this contract.
        // But the constructor sets owner = msg.sender, and the test contract deploys c,
        // so owner is the test contract. Hence, any call from this test contract is an owner call.
        // Thus, we cannot test non-owner calls without a proxy or separate caller contract.
        // The rule must be something we can test from the owner's perspective.
        // Let's choose a different rule: an owner call to withdrawAll succeeds and sets balance to 0.
        // However, that rule is already accepted. We need a different rule.
        // Let's test: after any successful owner withdrawal, the contract's balance decreases by exactly the withdrawn amount.
        // But that's also accepted. We need a fresh rule.
        // Consider: depositsCount can only be incremented by receiving Ether, and never decremented.
        // So after any sequence of calls, depositsCount >= initial depositsCount.
        // But we need a single call rule.
        // Rule: sendMoney with value greater than balance reverts, leaving depositsCount unchanged.
        // Let's try that.
        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount();
        uint amount = balBefore + 1; // more than balance

        bool reverted;
        try c.sendMoney(caller, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && address(c).balance == balBefore && c.depositsCount() == countBefore);
    }

    receive() external payable {}
}

