    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // Ensure the owner calls withdrawAll: the test contract is the owner.
        // (The constructor of C sets owner = msg.sender = address(this).)

        // Optionally, send some Ether to c so that withdrawAll has something to withdraw.
        // Use a parameter? The rule should hold for any initial balance, but we can't control it.
        // We can just call withdrawAll on the current balance.

        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule: if withdrawAll does not revert, the balance after must be zero.
        // If it reverts, the balance must remain unchanged.
        // But the rule we want: after owner's withdrawAll, balance becomes zero.
        // To avoid issues when the initial balance is zero, we can require balBefore > 0?
        // But the rule should be general: for any balance, after withdrawAll (if succeeds) balance is 0.
        // Actually, withdrawAll always succeeds for owner (transfer of full balance is always possible).
        // So we can assert that reverted is false and balAfter == 0.
        assert(!reverted && balAfter == 0);
    }

    receive() external payable {}
}

